insert into public.bible_verses (id, book_key, book_name, chapter, verse, content, sort_order)
values
('jer-23-16','jer','예레미야',23,16,'만군의 여호와께서 이와 같이 말씀하시되 너희에게 예언하는 선지자들의 말을 듣지 말라 그들은 너희에게 헛된 것을 가르치나니 그들이 말한 묵시는 자기 마음으로 말미암은 것이요 여호와의 입에서 나온 것이 아니니라',19501),
('jer-23-17','jer','예레미야',23,17,'항상 그들이 나를 멸시하는 자에게 이르기를 너희가 평안하리라 여호와의 말씀이니라 하며 또 자기 마음이 완악한 대로 행하는 모든 사람에게 이르기를 재앙이 너희에게 임하지 아니하리라 하였느니라',19502),
('jer-23-18','jer','예레미야',23,18,'누가 여호와의 회의에 참여하여 그 말을 알아들었으며 누가 귀를 기울여 그 말을 들었느냐',19503),
('jer-23-19','jer','예레미야',23,19,'보라 여호와의 노여움이 일어나 폭풍과 회오리바람처럼 악인의 머리를 칠 것이라',19504),
('jer-23-20','jer','예레미야',23,20,'여호와의 진노가 내 마음의 뜻하는 바를 행하여 이루기까지는 그치지 아니하나니 너희가 끝날에 그것을 완전히 깨달으리라',19505),
('jer-23-21','jer','예레미야',23,21,'이 선지자들은 내가 보내지 아니하였어도 달음질하며 내가 그들에게 이르지 아니하였어도 예언하였은즉',19506),
('jer-23-22','jer','예레미야',23,22,'그들이 만일 나의 회의에 참여하였더라면 내 백성에게 내 말을 들려서 그들을 악한 길과 악한 행위에서 돌이키게 하였으리라',19507),
('jer-23-23','jer','예레미야',23,23,'여호와의 말씀이니라 나는 가까운 데에 있는 하나님이요 먼 데에 있는 하나님은 아니냐',19508),
('jer-23-24','jer','예레미야',23,24,'여호와의 말씀이니라 사람이 내게 보이지 아니하려고 누가 자신을 은밀한 곳에 숨길 수 있겠느냐 여호와가 말하노라 나는 천지에 충만하지 아니하냐',19509),
('jer-23-25','jer','예레미야',23,25,'내 이름으로 거짓을 예언하는 선지자들의 말에 내가 꿈을 꾸었다 꿈을 꾸었다고 말하는 것을 내가 들었노라',19510),
('jer-23-26','jer','예레미야',23,26,'거짓을 예언하는 선지자들이 언제까지 이 마음을 품겠느냐 그들은 그 마음의 간교한 것을 예언하느니라',19511),
('jer-23-27','jer','예레미야',23,27,'그들이 서로 꿈 꾼 것을 말하니 그 생각인즉 그들의 조상들이 바알로 말미암아 내 이름을 잊어버린 것 같이 내 백성으로 내 이름을 잊게 하려 함이로다',19512),
('jer-23-28','jer','예레미야',23,28,'여호와의 말씀이니라 꿈을 꾼 선지자는 꿈을 말할 것이요 내 말을 받은 자는 성실함으로 내 말을 말할 것이라 겨가 어찌 알곡과 같겠느냐',19513),
('jer-23-29','jer','예레미야',23,29,'여호와의 말씀이니라 내 말이 불 같지 아니하냐 바위를 쳐서 부스러뜨리는 방망이 같지 아니하냐',19514),
('jer-23-30','jer','예레미야',23,30,'여호와의 말씀이라 그러므로 보라 서로 내 말을 도둑질하는 선지자들을 내가 치리라',19515),
('jer-23-31','jer','예레미야',23,31,'여호와의 말씀이니라 보라 그들이 혀를 놀려 여호와가 말씀하셨다 하는 선지자들을 내가 치리라',19516),
('jer-23-32','jer','예레미야',23,32,'여호와의 말씀이니라 보라 거짓 꿈을 예언하여 이르며 거짓과 헛된 자만으로 내 백성을 미혹하게 하는 자를 내가 치리라 내가 그들을 보내지 아니하였으며 명령하지 아니하였나니 그들은 이 백성에게 아무 유익이 없느니라 여호와의 말씀이니라',19517),
('jer-23-33','jer','예레미야',23,33,'이 백성이나 선지자나 제사장이 네게 물어 이르기를 여호와의 엄중한 말씀이 무엇인가 묻거든 너는 그들에게 대답하기를 엄중한 말씀이 무엇이냐 묻느냐 여호와의 말씀에 내가 너희를 버리리라 하셨고',19518),
('jer-23-34','jer','예레미야',23,34,'또 여호와의 엄중한 말씀이라 하는 선지자에게나 제사장에게나 백성에게는 내가 그 사람과 그 집안을 벌하리라 하셨다 하고',19519),
('jer-23-35','jer','예레미야',23,35,'너희는 서로 이웃과 형제에게 묻기를 여호와께서 무엇이라 응답하셨으며 여호와께서 무엇이라 말씀하셨느냐 하고',19520),
('jer-23-36','jer','예레미야',23,36,'다시는 여호와의 엄중한 말씀이라 말하지 말라 각 사람의 말이 자기에게 중벌이 되리니 이는 너희가 살아 계신 하나님, 만군의 여호와 우리 하나님의 말씀을 망령되이 사용함이니라 하고',19521),
('jer-23-37','jer','예레미야',23,37,'너는 또 선지자에게 말하기를 여호와께서 네게 무엇이라 대답하셨으며 여호와께서 무엇이라 말씀하셨느냐',19522),
('jer-23-38','jer','예레미야',23,38,'너희는 여호와의 엄중한 말씀이라 말하도다 그러므로 여호와께서 이와 같이 말씀하시되 내가 너희에게 사람을 보내어 이 말씀은 여호와의 엄중한 말씀이니 너희는 말하지 말라 하였으나 너희가 여호와의 엄중한 말씀이라 하였은즉',19523),
('jer-23-39','jer','예레미야',23,39,'내가 너희를 온전히 잊어버리며 내가 너희와 너희 조상들에게 준 이 성읍을 내 앞에서 내버려',19524),
('jer-23-40','jer','예레미야',23,40,'너희는 영원한 치욕과 잊지 못할 영구한 수치를 당하게 하리라 하셨느니라',19525),
('jer-24-1','jer','예레미야',24,1,'바벨론의 느부갓네살 왕이 유다 왕 여호야김의 아들 여고냐와 유다 고관들과 목공들과 철공들을 예루살렘에서 바벨론으로 옮긴 후에 여호와께서 여호와의 성전 앞에 놓인 무화과 두 광주리를 내게 보이셨는데',19526),
('jer-24-2','jer','예레미야',24,2,'한 광주리에는 처음 익은 듯한 극히 좋은 무화과가 있고 한 광주리에는 나빠서 먹을 수 없는 극히 나쁜 무화과가 있더라',19527),
('jer-24-3','jer','예레미야',24,3,'여호와께서 내게 이르시되 예레미야야 네가 무엇을 보느냐 하시매 내가 대답하되 무화과이온데 그 좋은 무화과는 극히 좋고 그 나쁜 것은 아주 나빠서 먹을 수 없게 나쁘니이다 하니',19528),
('jer-24-4','jer','예레미야',24,4,'여호와의 말씀이 또 내게 임하니라 이르시되',19529),
('jer-24-5','jer','예레미야',24,5,'이스라엘의 하나님 여호와께서 이와 같이 말씀하시니라 내가 이 곳에서 옮겨 갈대아인의 땅에 이르게 한 유다 포로를 이 좋은 무화과 같이 잘 돌볼 것이라',19530),
('jer-24-6','jer','예레미야',24,6,'내가 그들을 돌아보아 좋게 하여 다시 이 땅으로 인도하여 세우고 헐지 아니하며 심고 뽑지 아니하겠고',19531),
('jer-24-7','jer','예레미야',24,7,'내가 여호와인 줄 아는 마음을 그들에게 주어서 그들이 전심으로 내게 돌아오게 하리니 그들은 내 백성이 되겠고 나는 그들의 하나님이 되리라',19532),
('jer-24-8','jer','예레미야',24,8,'여호와께서 이와 같이 말씀하시니라 내가 유다의 왕 시드기야와 그 고관들과 예루살렘의 남은 자로서 이 땅에 남아 있는 자와 애굽 땅에 사는 자들을 나빠서 먹을 수 없는 이 나쁜 무화과 같이 버리되',19533),
('jer-24-9','jer','예레미야',24,9,'세상 모든 나라 가운데 흩어서 그들에게 환난을 당하게 할 것이며 또 그들에게 내가 쫓아 보낼 모든 곳에서 부끄러움을 당하게 하며 말 거리가 되게 하며 조롱과 저주를 받게 할 것이며',19534),
('jer-24-10','jer','예레미야',24,10,'내가 칼과 기근과 전염병을 그들 가운데 보내 그들이 내가 그들과 그들의 조상들에게 준 땅에서 멸절하기까지 이르게 하리라 하시니라',19535),
('jer-25-1','jer','예레미야',25,1,'유다의 왕 요시야의 아들 여호야김 넷째 해 곧 바벨론의 왕 느부갓네살 원년에 유다의 모든 백성에 관한 말씀이 예레미야에게 임하니라',19536),
('jer-25-2','jer','예레미야',25,2,'선지자 예레미야가 유다의 모든 백성과 예루살렘의 모든 주민에게 말하여 이르되',19537),
('jer-25-3','jer','예레미야',25,3,'유다의 왕 아몬의 아들 요시야 왕 열셋째 해부터 오늘까지 이십삼 년 동안 여호와의 말씀이 내게 임하기로 내가 너희에게 꾸준히 일렀으나 너희가 순종하지 아니하였느니라',19538),
('jer-25-4','jer','예레미야',25,4,'그러므로 여호와께서 그의 모든 종 선지자를 너희에게 끊임없이 보내셨으나 너희가 순종하지 아니하였으며 귀를 기울여 듣지도 아니하였도다',19539),
('jer-25-5','jer','예레미야',25,5,'그가 이르시기를 너희는 각자의 악한 길과 악행을 버리고 돌아오라 그리하면 나 여호와가 너희와 너희 조상들에게 영원부터 영원까지 준 그 땅에 살리라',19540),
('jer-25-6','jer','예레미야',25,6,'너희는 다른 신을 따라다니며 섬기거나 경배하지 말며 너희 손으로 만든 것으로써 나의 노여움을 일으키지 말라 그리하면 내가 너희를 해하지 아니하리라 하였으나',19541),
('jer-25-7','jer','예레미야',25,7,'너희가 내 말을 순종하지 아니하고 너희 손으로 만든 것으로써 나의 노여움을 일으켜 스스로 해하였느니라 여호와의 말씀이니라',19542),
('jer-25-8','jer','예레미야',25,8,'그러므로 만군의 여호와께서 이와 같이 말씀하시니라 너희가 내 말을 듣지 아니하였느니라',19543),
('jer-25-9','jer','예레미야',25,9,'보라 내가 북쪽 모든 종족과 내 종 바벨론의 왕 느부갓네살을 불러다가 이 땅과 그 주민과 사방 모든 나라를 쳐서 진멸하여 그들을 놀램과 비웃음 거리가 되게 하며 땅으로 영원한 폐허가 되게 할 것이라 여호와의 말씀이니라',19544),
('jer-25-10','jer','예레미야',25,10,'내가 그들 중에서 기뻐하는 소리와 즐거워하는 소리와 신랑의 소리와 신부의 소리와 맷돌 소리와 등불 빛이 끊어지게 하리니',19545),
('jer-25-11','jer','예레미야',25,11,'이 모든 땅이 폐허가 되어 놀랄 일이 될 것이며 이 민족들은 칠십 년 동안 바벨론의 왕을 섬기리라',19546),
('jer-25-12','jer','예레미야',25,12,'여호와의 말씀이니라 칠십 년이 끝나면 내가 바벨론의 왕과 그의 나라와 갈대아인의 땅을 그 죄악으로 말미암아 벌하여 영원히 폐허가 되게 하되',19547),
('jer-25-13','jer','예레미야',25,13,'내가 그 땅을 향하여 선언한 바 곧 예레미야가 모든 민족을 향하여 예언하고 이 책에 기록한 나의 모든 말을 그 땅에 임하게 하리라',19548),
('jer-25-14','jer','예레미야',25,14,'그리하여 여러 민족과 큰 왕들이 그들로 자기들을 섬기게 할 것이나 나는 그들의 행위와 그들의 손이 행한 대로 갚으리라',19549),
('jer-25-15','jer','예레미야',25,15,'이스라엘의 하나님 여호와께서 이같이 내게 이르시되 너는 내 손에서 이 진노의 술잔을 받아가지고 내가 너를 보내는 바 그 모든 나라로 하여금 마시게 하라',19550),
('jer-25-16','jer','예레미야',25,16,'그들이 마시고 비틀거리며 미친 듯이 행동하리니 이는 내가 그들 중에 칼을 보냈기 때문이니라 하시기로',19551),
('jer-25-17','jer','예레미야',25,17,'내가 여호와의 손에서 그 잔을 받아서 여호와께서 나를 보내신 바 그 모든 나라로 마시게 하되',19552),
('jer-25-18','jer','예레미야',25,18,'예루살렘과 유다 성읍들과 그 왕들과 그 고관들로 마시게 하였더니 그들이 멸망과 놀램과 비웃음과 저주를 당함이 오늘과 같으니라',19553),
('jer-25-19','jer','예레미야',25,19,'또 애굽의 왕 바로와 그의 신하들과 그의 고관들과 그의 모든 백성과',19554),
('jer-25-20','jer','예레미야',25,20,'모든 섞여 사는 민족들과 우스 땅의 모든 왕과 블레셋 사람의 땅 모든 왕과 아스글론과 가사와 에그론과 아스돗의 나머지 사람들과',19555),
('jer-25-21','jer','예레미야',25,21,'에돔과 모압과 암몬 자손과',19556),
('jer-25-22','jer','예레미야',25,22,'두로의 모든 왕과 시돈의 모든 왕과 바다 건너쪽 섬의 왕들과',19557),
('jer-25-23','jer','예레미야',25,23,'드단과 데마와 부스와 살쩍을 깎은 모든 자와',19558),
('jer-25-24','jer','예레미야',25,24,'아라비아의 모든 왕과 광야에서 섞여 사는 민족들의 모든 왕과',19559),
